CREATE MATERIALIZED VIEW mv REFRESH EVERY 1 HOUR TO t AS SELECT 1;

CREATE MATERIALIZED VIEW mv REFRESH AFTER 30 MINUTE ENGINE = MergeTree ORDER BY a AS SELECT 1 AS a;

CREATE MATERIALIZED VIEW mv REFRESH EVERY 1 DAY OFFSET 2 HOUR RANDOMIZE FOR 1 HOUR TO t AS SELECT 1;

CREATE MATERIALIZED VIEW mv REFRESH EVERY 1 HOUR 30 MINUTE TO t AS SELECT 1;

CREATE MATERIALIZED VIEW mv REFRESH EVERY 1 HOUR DEPENDS ON db.a, b TO t AS SELECT 1;

CREATE MATERIALIZED VIEW mv REFRESH EVERY 1 HOUR SETTINGS refresh_retries = 3 APPEND TO t AS SELECT 1;

CREATE MATERIALIZED VIEW mv ON CLUSTER c REFRESH EVERY 1 HOUR TO t EMPTY AS SELECT 1;

CREATE MATERIALIZED VIEW IF NOT EXISTS mv REFRESH EVERY 12 HOUR TO t (a, b) AS SELECT 1 AS a, 2 AS b;

CREATE MATERIALIZED VIEW mv
REFRESH EVERY 12 HOUR
TO t
AS
WITH src AS (SELECT 1 AS a)
SELECT a FROM src;
